const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const a = tok.slice(2, 2 + n);
const sm = new Array(4 * n).fill(0), lz = new Array(4 * n).fill(0);
function build(x, l, r) {
  if (l === r) { sm[x] = a[l]; return; }
  const mid = (l + r) >> 1;
  build(2 * x, l, mid);
  build(2 * x + 1, mid + 1, r);
  sm[x] = sm[2 * x] + sm[2 * x + 1];
}
function apply(x, l, r, v) { sm[x] += v * (r - l + 1); lz[x] += v; }
function push(x, l, r) {
  if (lz[x] !== 0) {
    const mid = (l + r) >> 1;
    apply(2 * x, l, mid, lz[x]);
    apply(2 * x + 1, mid + 1, r, lz[x]);
    lz[x] = 0;
  }
}
function update(x, l, r, ql, qr, v) {
  if (qr < l || r < ql) return;
  if (ql <= l && r <= qr) { apply(x, l, r, v); return; }
  push(x, l, r);
  const mid = (l + r) >> 1;
  update(2 * x, l, mid, ql, qr, v);
  update(2 * x + 1, mid + 1, r, ql, qr, v);
  sm[x] = sm[2 * x] + sm[2 * x + 1];
}
function query(x, l, r, ql, qr) {
  if (qr < l || r < ql) return 0;
  if (ql <= l && r <= qr) return sm[x];
  push(x, l, r);
  const mid = (l + r) >> 1;
  return query(2 * x, l, mid, ql, qr) + query(2 * x + 1, mid + 1, r, ql, qr);
}
build(1, 0, n - 1);
const out = [];
let pos = 2 + n;
for (let i = 0; i < q; i++) {
  if (tok[pos] === 1) {
    update(1, 0, n - 1, tok[pos + 1] - 1, tok[pos + 2] - 1, tok[pos + 3]);
    pos += 4;
  } else {
    out.push(query(1, 0, n - 1, tok[pos + 1] - 1, tok[pos + 2] - 1));
    pos += 3;
  }
}
console.log(out.join("\n"));

