import java.io.*;
import java.util.*;

public class Main {
    static long[] sm, lz;
    static long[] a;

    static void build(int x, int l, int r) {
        if (l == r) { sm[x] = a[l]; return; }
        int mid = (l + r) / 2;
        build(2 * x, l, mid);
        build(2 * x + 1, mid + 1, r);
        sm[x] = sm[2 * x] + sm[2 * x + 1];
    }

    static void apply(int x, int l, int r, long v) {
        sm[x] += v * (r - l + 1);
        lz[x] += v;
    }

    static void push(int x, int l, int r) {
        if (lz[x] != 0) {
            int mid = (l + r) / 2;
            apply(2 * x, l, mid, lz[x]);
            apply(2 * x + 1, mid + 1, r, lz[x]);
            lz[x] = 0;
        }
    }

    static void update(int x, int l, int r, int ql, int qr, long v) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) { apply(x, l, r, v); return; }
        push(x, l, r);
        int mid = (l + r) / 2;
        update(2 * x, l, mid, ql, qr, v);
        update(2 * x + 1, mid + 1, r, ql, qr, v);
        sm[x] = sm[2 * x] + sm[2 * x + 1];
    }

    static long query(int x, int l, int r, int ql, int qr) {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return sm[x];
        push(x, l, r);
        int mid = (l + r) / 2;
        return query(2 * x, l, mid, ql, qr) + query(2 * x + 1, mid + 1, r, ql, qr);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }
        sm = new long[4 * n];
        lz = new long[4 * n];
        build(1, 0, n - 1);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int t = (int) in.nval;
            in.nextToken();
            int l = (int) in.nval - 1;
            in.nextToken();
            int r = (int) in.nval - 1;
            if (t == 1) {
                in.nextToken();
                update(1, 0, n - 1, l, r, (long) in.nval);
            } else {
                out.append(query(1, 0, n - 1, l, r)).append('\n');
            }
        }
        System.out.print(out);
    }
}

