using namespace std;
typedef long long ll;
vector<ll> a, sm, lz;

void build(int x, int l, int r) {
    if (l == r) { sm[x] = a[l]; return; }
    int mid = (l + r) / 2;
    build(2 * x, l, mid);
    build(2 * x + 1, mid + 1, r);
    sm[x] = sm[2 * x] + sm[2 * x + 1];
}
void apply(int x, int l, int r, ll v) { sm[x] += v * (r - l + 1); lz[x] += v; }
void push(int x, int l, int r) {
    if (lz[x]) {
        int mid = (l + r) / 2;
        apply(2 * x, l, mid, lz[x]);
        apply(2 * x + 1, mid + 1, r, lz[x]);
        lz[x] = 0;
    }
}
void update(int x, int l, int r, int ql, int qr, ll v) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { apply(x, l, r, v); return; }
    push(x, l, r);
    int mid = (l + r) / 2;
    update(2 * x, l, mid, ql, qr, v);
    update(2 * x + 1, mid + 1, r, ql, qr, v);
    sm[x] = sm[2 * x] + sm[2 * x + 1];
}
ll query(int x, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return sm[x];
    push(x, l, r);
    int mid = (l + r) / 2;
    return query(2 * x, l, mid, ql, qr) + query(2 * x + 1, mid + 1, r, ql, qr);
}

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    a.resize(n);
    for (auto& x : a) scanf("%lld", &x);
    sm.assign(4 * n, 0);
    lz.assign(4 * n, 0);
    build(1, 0, n - 1);
    while (q--) {
        int t, l, r;
        scanf("%d %d %d", &t, &l, &r);
        l--; r--;
        if (t == 1) {
            ll v;
            scanf("%lld", &v);
            update(1, 0, n - 1, l, r, v);
        } else {
            printf("%lld\n", query(1, 0, n - 1, l, r));
        }
    }
    return 0;
}
